pub fn trims(s: &str) -> String {
    return format!("[{}|{}|{}]", php_trim(s), php_ltrim(s), php_rtrim(s));
}

pub fn firsts(s: &str) -> String {
    return format!("[{}|{}]", php_ucfirst(s), php_lcfirst(s));
}

pub fn replaced(search: &str, replace: &str, subject: &str) -> String {
    return format!("[{}]", php_replace(search, replace, subject));
}

pub fn pieces(separator: &str, s: &str) -> String {
    let parts = php_explode(separator, s);
    return format!("{}[{}]", parts.len() as i64, parts.join("|"));
}

fn php_trim(text: &str) -> String {
    text.trim_matches([' ', '\t', '\n', '\r', '\0', '\x0B'])
        .to_string()
}

fn php_ltrim(text: &str) -> String {
    text.trim_start_matches([' ', '\t', '\n', '\r', '\0', '\x0B'])
        .to_string()
}

fn php_rtrim(text: &str) -> String {
    text.trim_end_matches([' ', '\t', '\n', '\r', '\0', '\x0B'])
        .to_string()
}

fn php_ucfirst(text: &str) -> String {
    let mut text = text.to_string();
    if let Some(first) = text.get_mut(..1) {
        first.make_ascii_uppercase();
    }
    text
}

fn php_lcfirst(text: &str) -> String {
    let mut text = text.to_string();
    if let Some(first) = text.get_mut(..1) {
        first.make_ascii_lowercase();
    }
    text
}

fn php_replace(search: &str, replace: &str, subject: &str) -> String {
    if search.is_empty() {
        subject.to_string()
    } else {
        subject.replace(search, replace)
    }
}

fn php_explode(separator: &str, text: &str) -> Vec<String> {
    assert!(
        !separator.is_empty(),
        "explode(): separator must not be empty"
    );
    text.split(separator).map(str::to_owned).collect()
}

